#include <string.h>

int main(void)
{
    long long x;
    int k, i;
    char op[8];

    if (scanf("%lld %d", &x, &k) != 2)
        return 0;
    for (i = 0; i < k; i++) {
        long long m = 0;

        if (scanf("%7s", op) != 1)
            return 0;
        if (strcmp(op, "++") == 0) {
            x++;
        } else if (strcmp(op, "--") == 0) {
            x--;
        } else {
            if (scanf("%lld", &m) != 1)
                return 0;
            if (strcmp(op, "+") == 0)
                x += m;
            else if (strcmp(op, "-") == 0)
                x -= m;
            else if (strcmp(op, "*") == 0)
                x *= m;
            else if (strcmp(op, "/") == 0)
                x /= m;
            else if (strcmp(op, "%") == 0)
                x %= m;
        }
    }
    printf("%lld\n", x);
    return 0;
}

