import sys

def trunc_div(a, b):
    q = abs(a) // abs(b)
    if (a < 0) != (b < 0):
        q = -q
    return q

def main():
    data = sys.stdin.read().split()
    if len(data) < 2:
        return

    x = int(data[0])
    k = int(data[1])
    pos = 2

    for _ in range(k):
        op = data[pos]
        pos += 1
        if op == "++":
            x += 1
        elif op == "--":
            x -= 1
        else:
            m = int(data[pos])
            pos += 1
            if op == "+":
                x += m
            elif op == "-":
                x -= m
            elif op == "*":
                x *= m
            elif op == "/":
                x = trunc_div(x, m)
            elif op == "%":
                x = x - trunc_div(x, m) * m

    print(x)

if __name__ == "__main__":
    main()

