    int count = 0;
    int inNum = 0;
    long long sum = 0;
    long long max = 0;
    long long cur = 0;

    while ((ch = getchar()) != EOF && ch != '\n') {
        if (ch >= '0' && ch <= '9') {
            cur = cur * 10 + (ch - '0');
            inNum = 1;
        } else if (inNum) {
            count++;
            sum += cur;
            if (count == 1 || cur > max)
                max = cur;
            cur = 0;
            inNum = 0;
        }
    }

    if (inNum) {
        count++;
        sum += cur;
        if (count == 1 || cur > max)
            max = cur;
    }

    printf("count: %d\n", count);
    printf("sum: %lld\n", sum);
    if (count == 0)
        printf("max: NONE\n");
    else
        printf("max: %lld\n", max);
    return 0;
}

